#!/usr/bin/env python3
"""Run from project root: python3 fix_brand.py"""
import base64, os, sys
if not os.path.exists("app"):
    print("ERROR: run from project root (where app/ exists)"); sys.exit(1)

# Binary files (PNG, ICO) — decode bytes
BINARY = {
    "public/icon-32.png": "",
    "public/icon-48.png": "",
    "public/icon-96.png": "",
    "public/icon-192.png": "",
    "public/icon-512.png": "",
    "public/apple-icon-180.png": "",
    "public/favicon.ico": "",
    "public/og-banner.png": "",
}
for path, enc in BINARY.items():
    d = os.path.dirname(path)
    if d: os.makedirs(d, exist_ok=True)
    open(path, "wb").write(base64.b64decode(enc))
    print(f"WRITTEN  {path}  ({os.path.getsize(path)//1024}KB)")

# Text files — decode as UTF-8 with explicit newline
TEXT = {
    "app/layout.tsx": "",
    "app/page.tsx": "",
}
for path, enc in TEXT.items():
    d = os.path.dirname(path)
    if d: os.makedirs(d, exist_ok=True)
    content = base64.b64decode(enc).decode("utf-8")
    open(path, "w", encoding="utf-8", newline="\n").write(content)
    print(f"WRITTEN  {path}  ({len(content.splitlines())} lines)")

print("""
BRAND ASSETS DEPLOYED

Files written:
  public/favicon.ico              Multi-resolution favicon
  public/icon-{32,48,96,192,512}  PWA icon set
  public/apple-icon-180.png        iOS home screen
  public/og-banner.png             1500x500 social card
  app/layout.tsx                   + full OG/Twitter metadata
                                   + theme-color #10B981
                                   + favicon links
  app/page.tsx                     + uses /icon-512.png as logo
                                   + new slogan
                                   + routes to /terminal (not /auth/signin)
                                   + status strip at bottom

Verification after deploy:
  1. Visit https://abraxas-app.vercel.app/ — green splash logo loads
  2. Tab favicon shows green diamond mark
  3. Paste URL into iMessage / Slack / Twitter — preview shows banner
  4. Test on opengraph.xyz/url/abraxas-app.vercel.app for card preview

Run:
  npm run build
  git add -A
  git commit -m \"feat: brand assets — green splash logo, OG banner, favicon, refreshed splash\"
  git push origin main
""")
